output_text:
[
  {
    "id": "take_cart_at_bay",
    "text": "A shopper must take a cart from the cart bay near the entrance before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)"
      },
      "events": {
        "takeCartAtBay": {
          "pre": {
            "and": [
              "cartBay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCartAtBay"
    }
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Carts are prohibited inside single-file shelf aisles where shelves line both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontal": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelfCanyon": {
          "and": [
            "singleFileHorizontal",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "shelfCanyon"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_shelf_canyon",
    "text": "A shopper must not push a cart into a single-file shelf canyon.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontal": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelfCanyon": {
          "and": [
            "singleFileHorizontal",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterShelfCanyonWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "shelfCanyon"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterShelfCanyonWithCart"
    }
  },
  {
    "id": "park_cart_only_in_wide_mouth",
    "text": "If a shopper parks or releases a cart, they may do so only in a wide open aisle mouth rather than beside shelves or in a narrow aisle.",
    "abstraction": {
      "state_properties": {
        "wideOpenMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "wideOpenMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks a cart to enter a pedestrian-only aisle, they are obliged to return and pick the cart up before the trip ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCart",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "no_cartless_wide_aisle_interact",
    "text": "Cartless interactions in wide aisles are prohibited except when the interaction is picking the cart back up.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "wideAisle",
          "INTERACT",
          {
            "not": "pickUpCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_traffic_no_west",
    "text": "While pushing a cart, shoppers must follow the one-way cart flow and may not move west.",
    "abstraction": {
      "state_properties": {
        "pushingCart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pushingCart",
          "W"
        ]
      }
    }
  },
  {
    "id": "exit_after_item_pickup",
    "text": "After picking a required item from a shelf, whether with the cart in a wide aisle or on foot in a single-file shelf aisle, the shopper is obliged eventually to leave through the exit.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontal": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelfCanyon": {
          "and": [
            "singleFileHorizontal",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "itemPickupWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "adjShelf",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        },
        "itemPickupOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "shelfCanyon",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "or": [
          "itemPickupWithCart",
          "itemPickupOnFoot"
        ]
      },
      "discharge": "EXIT"
    }
  }
]
